  // ============================================================
  // 📊 دوال مساعدة
  // ============================================================

  // الحصول على جميع الأدوية
  static List<Map<String, dynamic>> getAll() {
    return allMedicines;
  }

  // الحصول على الأدوية حسب التصنيف
  static List<Map<String, dynamic>> getByCategory(String category) {
    if (category == 'الكل') return allMedicines;
    return allMedicines.where((med) => med['category'] == category).toList();
  }

  // البحث عن دواء
  static List<Map<String, dynamic>> search(String query) {
    if (query.isEmpty) return allMedicines;
    return allMedicines.where((med) {
      final name = med['name'] as String;
      final description = med['description'] as String;
      return name.contains(query) || description.contains(query);
    }).toList();
  }

  // الحصول على التصنيفات الفريدة
  static List<String> getCategories() {
    final categories = allMedicines.map((med) => med['category'] as String).toSet().toList();
    return ['الكل', ...categories];
  }

  // الحصول على الأدوية المتوفرة
  static List<Map<String, dynamic>> getInStock() {
    return allMedicines.where((med) => med['inStock'] == true).toList();
  }

  // الحصول على الأدوية التي تحتاج وصفة طبية
  static List<Map<String, dynamic>> getRequiringPrescription() {
    return allMedicines.where((med) => med['requiresPrescription'] == true).toList();
  }
}
